// Generated by Torque Lift. Do not edit: Torque Lift regenerates it.
// The browser side of Torque Lift for a server-rendered app, around the vendored Jitsu SDK
// (./jitsu.es.js). It sends only page views and identifies, named by route template, and only
// from a production page with Torque Lift's write key, in a browser that is not automated, after
// analytics consent. Otherwise it sends nothing and sets no cookie. It also remembers where the
// visitor came from (see `landing()`) and sends that on every call.
//
// While consent holds it keeps the first-party cookie `torque_lift_aid`, which holds Jitsu's
// anonymous ID so the server can send events and read experiment flags for the same visitor. The
// cookie is deleted on withdrawal and on reset().
import { jitsuAnalytics } from "./jitsu.es.js";

export const COOKIE = "torque_lift_aid";
const ONE_YEAR = 60 * 60 * 24 * 365;
// The longest campaign tag the pipeline keeps (Event and Data Contract, `string_value`).
const MAX_TAG_LENGTH = 256;

let config = null;
let client;
let consent = false;
let route;
let userId = null;
let remembered;

/** Set the write key, the collector host and the plan's globals. The server renders them from the
 * deployment's environment, in production only, so a development page sends nothing. */
export function configure(next) {
  config = next;
  client = undefined;
}

function offReason() {
  if (!config || !config.writeKey || !config.host) {
    return "the write key or the collector host is not set";
  }
  if (navigator.webdriver) return "the browser is automated";
  return null;
}

function analytics() {
  if (typeof window === "undefined") return null;
  if (client === undefined) {
    const reason = offReason();
    if (reason !== null) {
      console.debug(`[torque] analytics is off: ${reason}. Calls are logged, not sent.`);
      client = null;
    } else {
      client = jitsuAnalytics({ host: config.host, writeKey: config.writeKey, privacy: privacy() });
    }
  }
  return client;
}

function privacy() {
  return { dontSend: !consent, ipPolicy: "remove", consentCategories: { analytics: consent } };
}

function referrerHost() {
  try {
    return document.referrer ? new URL(document.referrer).host : "";
  } catch {
    return "";
  }
}

/** Where this page session began: the referrer's host and the landing URL's utm_source,
 * utm_medium and utm_campaign. A visitor may accept analytics after clicking through, so Jitsu's
 * per-call read of the URL would lose the campaign; this keeps it in this variable only, never in
 * a cookie or storage, so nothing is stored before consent. Only these three tags are kept: the
 * rest of the query string may carry a token or an email. */
function landing() {
  if (remembered === undefined) {
    const campaign = {};
    try {
      const query = new URLSearchParams(window.location.search);
      for (const [tag, key] of [
        ["utm_source", "source"],
        ["utm_medium", "medium"],
        ["utm_campaign", "name"],
      ]) {
        const value = (query.get(tag) ?? "").trim();
        if (value !== "" && value.length <= MAX_TAG_LENGTH) campaign[key] = value;
      }
    } catch {
      // A browser that cannot parse its own URL sends no campaign.
    }
    remembered = { referrer: referrerHost(), campaign };
  }
  return remembered;
}

// The landing URL is gone after the first navigation, so read it as soon as this loads.
if (typeof window !== "undefined") landing();

/** Context for every call: the plan's globals, the route template, the landing campaign tags and
 * the landing referrer's host, with no query string, fragment, title or full referrer. */
function context() {
  const { origin, pathname } = window.location;
  const page = { url: origin + pathname, search: "", title: "", referrer: landing().referrer };
  if (route !== undefined) page.route = route;
  const result = { ...((config && config.context) || {}), page };
  if (Object.keys(landing().campaign).length > 0) result.campaign = landing().campaign;
  return result;
}

function send(call, args, run) {
  const a = analytics();
  if (a === null) {
    if (typeof window !== "undefined") console.debug("[torque]", call, ...args);
    return;
  }
  void run(a);
}

function secure() {
  return window.location.protocol === "https:" ? "; Secure" : "";
}

/** Keep `torque_lift_aid` equal to Jitsu's anonymous ID while consent holds; delete it otherwise. */
function syncCookie() {
  if (!consent) {
    document.cookie = `${COOKIE}=; Max-Age=0; Path=/; SameSite=Lax${secure()}`;
    return;
  }
  const user = analytics()?.user();
  const id = user && user.anonymousId;
  if (id) {
    document.cookie = `${COOKIE}=${encodeURIComponent(id)}; Max-Age=${ONE_YEAR}; Path=/; SameSite=Lax${secure()}`;
  }
}

/** Record the visitor's analytics consent. Nothing is sent, and no cookie set, until true. When
 * consent is given on the page already counted, that page view is sent now (`resend`); the boot
 * module turns it off because it sends the page view of the page it is starting on itself. */
export function setAnalyticsConsent(granted, resend = true) {
  const changed = granted !== consent;
  consent = granted;
  analytics()?.configure({ privacy: privacy() });
  syncCookie();
  // The page view sent before consent was dropped: count the page the visitor accepted on.
  if (resend && changed && granted && route !== undefined) page(route);
}

/** Send a page view named by its route template, such as /projects/[pk], never by its URL. */
export function page(routeTemplate) {
  route = routeTemplate;
  if (typeof window === "undefined") return;
  const { origin, pathname } = window.location;
  const props = {
    ...((config && config.properties) || {}),
    name: routeTemplate,
    url: origin + pathname,
    search: "",
    hash: "",
    title: "",
    referrer: landing().referrer,
  };
  send("page", [props], (a) => a.page(props, { context: context() }));
  syncCookie();
}

/** Tie this browser to the signed-in user, with the plan's traits only. */
export function identify(user, traits) {
  send("identify", [user, traits], (a) => a.identify(user, { ...traits }, { context: context() }));
  userId = user;
}

/** The signed-in user the last identify() named, or null. */
export function currentUser() {
  return userId;
}

/** On logout: forget the user and traits, start a new anonymous ID and drop the cookie. */
export async function reset() {
  const a = analytics();
  if (a === null) {
    if (typeof window !== "undefined") console.debug("[torque]", "reset");
  } else {
    await a.reset();
  }
  userId = null;
  document.cookie = `${COOKIE}=; Max-Age=0; Path=/; SameSite=Lax${secure()}`;
  syncCookie();
}
